escenas.animacion:
const ac=A.accent, RED='#FF5A6E', ORG='#ff9a3c', ctx2=A.ctx;
A.bg('#0b1020','#05070f',true);
const R=4,C=8,ks=88,g=12;
const gw=C*(ks+g)-g, gh=R*(ks+g)-g;
const x0=540-gw/2, y0=500;
const kCada=A.k('cada',2.333), kTecla=A.k('tecla.',2.667), kTiene=A.k('Tiene',3.0), kEsc=A.k('escondida.',4.0);
const enter=A.p(0,0.7,'snapSettle');
const cableOut=A.p(kTiene,0.35,'accelExit');
const xray=A.p(kTiene,0.45,'softInOut');
const cx=(c)=>x0+c*(ks+g)+ks/2, cy=(r)=>y0+r*(ks+g)+ks/2;
const hub=[540,1050];
const cs=(i)=>0.75+i*0.03;
const rowT=(r)=>kTiene+0.05+r*0.13;
const colT=(c)=>3.4+c*0.045;
const hiKeys=[9,21,14];
const shake=(t>kTecla&&t<kTecla+0.3)?10*(1-(t-kTecla)/0.3):0;
A.with(()=>{
  A.rect(x0-30,y0-30,gw+60,gh+60,{r:28,fill:'#141a2e',stroke:'#3a4466',lw:4});
  for(let r=0;r<R;r++){
    const p=A.p(rowT(r),0.3,'whip');
    if(p>0){
      const pulse=Math.max(0,1-(t-rowT(r))/0.5);
      A.line([[x0-20,cy(r)],[x0+gw+20,cy(r)]],{stroke:ac,lw:9+8*pulse,progress:p});
    }
  }
  for(let c=0;c<C;c++){
    const p=A.p(colT(c),0.3,'whip');
    if(p>0) A.line([[cx(c),y0-20],[cx(c),y0+gh+20]],{stroke:'#ffffff',lw:6,progress:p,alpha:0.9});
  }
  const keyA=1-0.6*xray;
  for(let r=0;r<R;r++)for(let c=0;c<C;c++){
    const i=r*C+c;
    const s=A.clamp(enter*1.4-i*0.012);
    const sc=A.pop(i*0.012,0.5);
    const x=x0+c*(ks+g), y=y0+r*(ks+g);
    let blink=0;
    hiKeys.forEach((h,j)=>{if(h===i){const d=t-(kCada+j*0.12); if(d>0&&d<0.35) blink=1-d/0.35;}});
    const rp=t>rowT(r)?Math.max(0,1-(t-rowT(r)-c*0.03)/0.45):0;
    A.with(()=>{
      A.rect(x,y,ks,ks,{r:14,fill:'#2a3352',stroke:'#cfd8ff',lw:3,alpha:s*keyA});
      A.rect(x+10,y+8,ks-20,ks-26,{r:10,fill:'#36416a',alpha:s*keyA*0.9});
      if(blink>0) A.rect(x,y,ks,ks,{r:14,fill:RED,alpha:0.7*blink});
      if(rp>0&&rp<1) A.rect(x,y,ks,ks,{r:14,fill:ac,alpha:0.55*rp,glow:20*rp});
    },{x:x+ks/2,y:y+ks/2,scale:sc||0.001});
  }
  if(t>kEsc-0.1){
    for(let r=0;r<R;r++)for(let c=0;c<C;c++){
      const d=kEsc-0.1+(r+c)*0.03;
      const s=A.pop(d,0.3);
      if(s>0) A.circle(cx(c),cy(r),10*s,{fill:ac,glow:18*(0.6+0.4*Math.sin((t-d)*9))});
    }
  }
  if(t>=cs(0) && cableOut<1){
    for(let i=0;i<R*C;i++){
      const r=Math.floor(i/C), c=i%C;
      const p=A.p(cs(i),0.4,'glide');
      if(p<=0) continue;
      const sx=cx(c), sy=cy(r);
      const midY=y0+gh+22+r*9;
      let hl=0;
      hiKeys.forEach((h,j)=>{if(h===i){const d=t-(kCada+j*0.12); if(d>0&&d<0.35) hl=1-d/0.35;}});
      const col=hl>0?'#ffffff':(i%2?ORG:RED);
      A.line([[sx,sy],[sx,midY],[A.lerp(sx,hub[0],0.85),hub[1]-22],hub],{stroke:col,lw:2.5+4*hl,alpha:1-cableOut,progress:p});
      A.circle(sx,sy,6,{fill:col,alpha:p*(1-cableOut)});
    }
    const hp=A.p(cs(0)+0.2,0.4,'softLand');
    A.rect(hub[0]-50,hub[1]-6,100,30,{r:8,fill:RED,alpha:hp*(1-cableOut)});
  }
  const xp=A.p(kTecla,0.3,'crashIn')*(1-cableOut);
  if(xp>0){
    const L=150, Y=985, V=70;
    A.line([[540-L,Y-V],[540+L,Y+V]],{stroke:'#ff2a4a',lw:20,progress:xp});
    A.line([[540+L,Y-V],[540-L,Y+V]],{stroke:'#ff2a4a',lw:20,progress:A.clamp(xp*1.4-0.4)});
  }
},{x:540,y:800,shake});
A.flash(kTecla,0.22,0.2);
const fl=A.p(rowT(0),0.4,'softLand');
if(fl>0) A.with(()=>{A.text('filas',0,0,{size:50,color:ac,weight:'900',align:'center',stroke:'#05070f',strokeWidth:8});},{x:72,y:y0+gh/2,rot:-Math.PI/2,alpha:fl,scale:A.lerp(0.7,1,fl)});
const cl=A.p(colT(0),0.4,'softLand');
if(cl>0) A.text('columnas',540,1000+(1-cl)*20,{size:50,color:'#ffffff',weight:'900',align:'center',alpha:cl,stroke:'#05070f',strokeWidth:8});
if(t>kEsc){
  ctx2.save(); ctx2.beginPath(); ctx2.rect(0,400,1080,730); ctx2.clip();
  A.rings(540,y0+gh/2,kEsc,{count:3,speed:700,gap:0.18,maxR:520,color:ac,lw:4,alpha:0.5});
  ctx2.restore();
}
let n=0; for(let i=0;i<32;i++) if(t>=cs(i)+0.15) n++;
const a1=A.p(cs(0),0.3,'softLand');
if(a1>0){
  const mv=A.p(kTiene,0.5,'glide');
  const y=A.lerp(1500,1390,mv), sz=A.lerp(56,46,mv);
  A.text(Math.max(1,n)+' cables',540,y,{size:sz,color:RED,weight:'900',align:'center',alpha:1,stroke:'#05070f',strokeWidth:8});
  const st=A.p(kTiene,0.3,'crashIn');
  if(st>0){const w=A.lerp(150,125,mv)*st; A.line([[540-w,y],[540+w,y]],{stroke:'#ffffff',lw:4});}
}
const f1=A.p(rowT(0),0.4,'softLand'), f2=A.p(colT(0),0.4,'softLand');
if(f1>0) A.text('4 filas',445,1500+(1-f1)*20,{size:52,color:ac,weight:'900',align:'right',alpha:f1,stroke:'#05070f',strokeWidth:8});
if(f2>0) A.text('+ 8 columnas',465,1500+(1-f2)*20,{size:52,color:'#ffffff',weight:'900',align:'left',alpha:f2,stroke:'#05070f',strokeWidth:8});
const s3=A.pop(kEsc-0.05,0.45);
if(s3>0) A.with(()=>{
  A.text('=',-110,0,{size:56,color:'#ffffff',weight:'900',align:'right',stroke:'#05070f',strokeWidth:8});
  A.text('12',-50,0,{size:80,color:ac,weight:'900',align:'center',stroke:'#05070f',strokeWidth:10});
  A.text('cables',10,0,{size:56,color:'#ffffff',weight:'900',align:'left',stroke:'#05070f',strokeWidth:8});
},{x:540,y:1625,scale:s3});

const W=A.W, acc=A.accent, ORA='#FFB74D';
const tTec=A.k('teclas',1.0), tLam=A.k('láminas',1.667), tCam=A.k('caminos',2.333), tMet=A.k('metal:',3.0), tFil=A.k('filas',4.0), tCol=A.k('columnas.',5.0);
A.bg('#0B1626','#060C16',true);
const cols=5, rows=4, X0=260, DX=140, Y0=555, DY=150;
const cx=i=>X0+DX*i, cy=j=>Y0+DY*j;
const xL=185, xR=895, yT=480, yB=1080;
const zoom=1+0.035*A.clamp(t/A.dur);
A.with(()=>{
  // ---- LÁMINAS ----
  const pa=A.p(tLam-0.15,0.6,'snapSettle'), pb=A.p(tLam,0.6,'snapSettle');
  if(pb>0){
    const ox=A.lerp(900,0,pb);
    A.rect(xL-20+ox+14,yT-20+14,xR-xL+40,yB-yT+40,{r:22,fill:'rgba(255,183,77,0.06)',stroke:'rgba(255,220,180,0.45)',lw:3});
  }
  if(pa>0){
    const ox=A.lerp(-900,0,pa);
    A.rect(xL-20+ox,yT-20,xR-xL+40,yB-yT+40,{r:22,fill:'rgba(77,208,225,0.07)',stroke:'rgba(220,245,255,0.55)',lw:3});
    try{ A.lib.hatch(ctx,[[xL-20+ox,yT-20],[xR+20+ox,yT-20],[xR+20+ox,yB+20],[xL-20+ox,yB+20]],{angle:-0.7,spacing:26,width:1,color:'rgba(160,210,240,0.10)'}); }catch(e){}
  }
  // ---- CAMINOS: filas ----
  for(let j=0;j<rows;j++){
    const y=cy(j), pr=A.p(tCam+0.07*j,0.7,'glide');
    if(pr>0) A.line([[xL,y],[xR,y]],{stroke:'rgba(235,245,255,0.75)',lw:7,progress:pr});
    const pf=A.p(tFil-0.05+0.06*j,0.45,'glide');
    if(pf>0) A.line([[xL,y],[xR,y]],{stroke:acc,lw:10,progress:pf,glow:18});
  }
  // ---- CAMINOS: columnas ----
  for(let i=0;i<cols;i++){
    const x=cx(i), pr=A.p(tCam+0.25+0.07*i,0.7,'glide');
    if(pr>0) A.line([[x,yT],[x,yB]],{stroke:'rgba(255,235,210,0.6)',lw:7,progress:pr});
    const pc=A.p(tCol-0.05+0.05*i,0.4,'glide');
    if(pc>0) A.line([[x,yT],[x,yB]],{stroke:ORA,lw:10,progress:pc,glow:18});
  }
  // brillo de metal
  const gm=(t-tMet)/0.8;
  if(gm>0&&gm<1){
    for(let j=0;j<rows;j++){
      const g=A.clamp(gm*1.3-j*0.1);
      if(g>0&&g<1) A.circle(A.lerp(xL,xR,g),cy(j),9,{fill:'#FFFFFF',glow:30,alpha:Math.sin(g*Math.PI)});
    }
    for(let i=0;i<cols;i++){
      const g=A.clamp(gm*1.3-i*0.08);
      if(g>0&&g<1) A.circle(cx(i),A.lerp(yT,yB,g),8,{fill:'#FFFFFF',glow:26,alpha:0.8*Math.sin(g*Math.PI)});
    }
  }
  // pulsos por filas
  if(t>tFil+0.2){
    for(let j=0;j<rows;j++){
      const u=((t-tFil-0.2)*0.9+j*0.27)%1;
      A.circle(A.lerp(xL,xR,u),cy(j),8,{fill:'#E0FBFF',glow:24,alpha:0.9});
    }
  }
  if(t>tCol+0.15){
    for(let i=0;i<cols;i++){
      const u=((t-tCol-0.15)*1.1+i*0.2)%1;
      A.circle(cx(i),A.lerp(yT,yB,u),8,{fill:'#FFF0D8',glow:24,alpha:0.9});
    }
  }
  // cruces
  for(let j=0;j<rows;j++)for(let i=0;i<cols;i++){
    const s=A.pop(tCol+0.1+0.02*(i+j*cols),0.35);
    if(s>0) A.circle(cx(i),cy(j),20*s,{stroke:'#FFFFFF',lw:3,alpha:0.85});
  }
  // ---- TECLAS ----
  const lift=A.p(tTec-0.15,0.8,'whip');
  const keys=['1','2','3','4','5','Q','W','E','R','T','A','S','D','F','G','Z','X','C','V','B'];
  for(let j=0;j<rows;j++)for(let i=0;i<cols;i++){
    const n=j*cols+i;
    const ap=A.pop(0.02*n,0.4);
    if(ap<=0) continue;
    const dy=-40*lift - 8*Math.sin(t*2+n)*lift;
    A.with(()=>{
      const s=118;
      A.rect(cx(i)-s/2,cy(j)-s/2+10,s,s,{r:18,fill:'#05090F',alpha:1-lift});
      A.rect(cx(i)-s/2,cy(j)-s/2,s,s,{r:18,fill:'#1B2A3E',alpha:1-0.88*lift,stroke:'rgba(230,240,255,0.7)',lw:3});
      A.text(keys[n],cx(i),cy(j)+16,{size:46,color:'#FFFFFF',weight:'800',align:'center',alpha:1-0.75*lift});
    },{x:cx(i),y:cy(j),scale:ap,alpha:1-0.45*lift});
    void dy;
  }
},{x:540,y:780,scale:zoom});
// ---- ETIQUETAS ----
const lOut=1-A.p(tFil-0.35,0.3,'accelExit');
if(t>=tLam-0.05&&lOut>0){
  const txt=t<tCam?'LÁMINAS':'CAMINOS DE METAL';
  const sc=t<tCam?A.pop(tLam-0.05,0.4):A.pop(tCam,0.4);
  A.label(txt,540,1470,{size:62,bg:'rgba(255,255,255,0.08)',color:'#FFFFFF',scale:sc,alpha:lOut});
}
const sF=A.pop(tFil,0.45);
if(sF>0){
  A.with(()=>{
    A.text('FILAS',300,1470,{size:78,color:acc,weight:'900',align:'center'});
    for(let r=0;r<3;r++) A.line([[200,1520+r*26],[400,1520+r*26]],{stroke:acc,lw:7,progress:A.p(tFil+0.1+r*0.06,0.4,'glide')});
  },{x:300,y:1500,scale:sF});
}
const sC=A.pop(tCol,0.45);
if(sC>0){
  A.with(()=>{
    A.text('COLUMNAS',780,1470,{size:78,color:ORA,weight:'900',align:'center'});
    for(let c=0;c<3;c++) A.line([[740+c*40,1505],[740+c*40,1600]],{stroke:ORA,lw:7,progress:A.p(tCol+0.1+c*0.05,0.35,'glide')});
  },{x:780,y:1500,scale:sC});
}
if(t>tFil) A.flash(tFil,0.25,0.12);
if(t>tCol) A.flash(tCol,0.25,0.12);

const ac = A.accent || '#7CFC00', c2 = '#00E5FF';
A.bg('#0a0f1e', '#04060d');
const tPres = A.k('presionar', 0, 1) || 0.333;
const tPress = tPres + 0.35;
const tUne = A.k('unen', 1.667), tFila = A.k('fila', 2.333), tCol = A.k('columna', 3.333);
const tCierra = A.k('cierra', 4.333), tCirc = A.k('circuito', 5.0), tCruce = A.k('cruce', 6.333);
const cols = [190, 330, 470, 610, 750, 890], rows = [540, 670, 800, 930, 1060];
const CX = 610, CY = 800;
const closed = t >= tCierra;

// ---------- VISTA EN PLANTA (zona principal) ----------
const shakeAmt = closed ? 12 * (1 - A.p(tCierra, 0.45, 'cruise')) : 0;
A.with(() => {
  // cables del chip (apagados)
  const wp = A.p(0.3, 0.8, 'glide');
  A.line([[170, 450], [CX, 450], [CX, 480]], { stroke: '#2c3a5a', lw: 6, progress: wp });
  A.line([[150, CY], [110, CY], [110, 478]], { stroke: '#2c3a5a', lw: 6, progress: wp });
  // chip
  const cs = A.pop(0.2, 0.45);
  A.with(() => {
    A.rect(50, 422, 120, 56, { r: 8, fill: closed ? '#1d3a12' : '#18203a', stroke: closed ? ac : '#7f8db0', lw: 3 });
    for (let i = 0; i < 4; i++) { A.rect(62 + i * 26, 414, 8, 8, { fill: '#7f8db0' }); A.rect(62 + i * 26, 478, 8, 8, { fill: '#7f8db0' }); }
    A.text('CHIP', 110, 460, { size: 26, color: closed ? ac : '#c8d2ea', weight: '800', align: 'center' });
  }, { x: 110, y: 450, scale: cs });

  // filas y columnas apagadas
  rows.forEach((y, j) => A.line([[150, y], [960, y]], { stroke: '#2a3756', lw: 7, progress: A.p(0.05 + j * 0.07, 0.7, 'glide') }));
  cols.forEach((x, i) => A.line([[x, 480], [x, 1100]], { stroke: '#2a3756', lw: 7, progress: A.p(0.15 + i * 0.07, 0.7, 'glide') }));
  // nodos de cruce
  rows.forEach((y, j) => cols.forEach((x, i) => {
    if (i === 3 && j === 2) return;
    A.circle(x, y, 7, { fill: '#0a0f1e', stroke: '#4a5a80', lw: 3, alpha: A.p(0.5 + (i + j) * 0.04, 0.4, 'softInOut') });
  }));

  // fila encendida
  if (t >= tFila) {
    const fp = A.p(tFila, 0.5, 'whip');
    A.line([[150, CY], [960, CY]], { stroke: ac, lw: 26, alpha: 0.18, progress: fp });
    A.line([[150, CY], [960, CY]], { stroke: ac, lw: 10, progress: fp });
    A.label('FILA', 880, CY - 52, { size: 40, bg: ac, color: '#05070f', scale: A.pop(tFila + 0.1, 0.45) });
  }
  // columna encendida
  if (t >= tCol) {
    const cp = A.p(tCol, 0.5, 'whip');
    A.line([[CX, 480], [CX, 1100]], { stroke: c2, lw: 26, alpha: 0.18, progress: cp });
    A.line([[CX, 480], [CX, 1100]], { stroke: c2, lw: 10, progress: cp });
    A.label('COLUMNA', CX + 140, 1060, { size: 40, bg: c2, color: '#05070f', scale: A.pop(tCol + 0.1, 0.45) });
  }

  // lazo cerrado con corriente
  if (closed) {
    const L = [[170, 450], [CX, 450], [CX, CY], [110, CY], [110, 478]];
    const lp = A.p(tCierra, 0.6, 'whip');
    A.line(L, { stroke: ac, lw: 30, alpha: 0.15, progress: lp });
    A.line(L, { stroke: ac, lw: 8, progress: lp });
    const seg = []; let tot = 0;
    for (let i = 0; i < L.length - 1; i++) { const d = Math.hypot(L[i + 1][0] - L[i][0], L[i + 1][1] - L[i][1]); seg.push(d); tot += d; }
    const at = s => { s = ((s % tot) + tot) % tot; for (let i = 0; i < seg.length; i++) { if (s <= seg[i]) { const q = s / seg[i]; return [A.lerp(L[i][0], L[i + 1][0], q), A.lerp(L[i][1], L[i + 1][1], q)]; } s -= seg[i]; } return L[L.length - 1]; };
    const n = 14, fa = A.p(tCierra + 0.3, 0.4, 'softInOut');
    for (let i = 0; i < n; i++) {
      const [px, py] = at(i * tot / n + (t - tCierra) * 520);
      A.circle(px, py, 9, { fill: '#ffffff', glow: 18, alpha: fa });
    }
  }

  // nodo protagonista
  if (t >= tUne) {
    const ns = A.pop(tUne + 0.15, 0.45);
    const pulse = closed ? 1 + 0.15 * Math.sin((t - tCierra) * 10) : 1;
    A.circle(CX, CY, 18 * ns * pulse, { fill: closed ? ac : '#ffffff', glow: closed ? 40 : 15 });
    if (closed) A.circle(CX, CY, 8 * ns, { fill: '#ffffff' });
  }
  if (t >= tUne) A.rings(CX, CY, tUne + 0.1, { count: 1, speed: 260, maxR: 90, color: '#ffffff', lw: 4 });
  if (closed) A.rings(CX, CY, tCierra, { count: 3, speed: 380, gap: 0.18, maxR: 220, color: ac, lw: 6 });
  if (t >= tCruce - 0.1) {
    A.rings(CX, CY, tCruce - 0.1, { count: 2, speed: 300, gap: 0.2, maxR: 160, color: '#ffffff', lw: 5 });
    A.label('¡CRUCE!', CX - 170, CY - 90, { size: 52, bg: '#ffffff', color: '#05070f', scale: A.pop(tCruce - 0.1, 0.4) });
  }

  // tecla sobre el cruce: aparece, se presiona y se encoge hasta volverse el nodo
  const kIn = A.pop(0.05, 0.5);
  const kPress = A.p(tPress - 0.15, 0.25, 'crashIn');
  const kOut = A.p(tUne, 0.5, 'accelExit');
  if (kOut < 1) {
    const sc = kIn * (1 - 0.1 * kPress) * (1 - kOut * 0.92);
    A.with(() => {
      const x0 = CX - 110, y0 = CY - 130, w = 220, h = 220, dep = 34 * (1 - kPress * 0.7);
      const skirt = [[x0, y0 + h - 30], [x0 + w, y0 + h - 30], [x0 + w, y0 + h + dep], [x0, y0 + h + dep]];
      A.rect(x0, y0 + 20, w, h + dep - 20, { r: 22, fill: '#121a30', stroke: '#c8d2ea', lw: 4 });
      A.lib.hatch(ctx, skirt, { angle: Math.PI / 4, spacing: 10, width: 2, color: 'rgba(200,210,234,0.35)' });
      A.rect(x0 + 8, y0, w - 16, h - 16, { r: 20, fill: '#1e2846', stroke: '#ffffff', lw: 4 });
      A.text('K', CX, CY - 10, { size: 110, color: '#ffffff', weight: '800', align: 'center' });
    }, { x: CX, y: CY, scale: sc, alpha: 1 - kOut });
    if (t > tPress - 0.4 && t < tUne + 0.2) {
      const aa = A.p(tPress - 0.4, 0.3, 'softLand') * (1 - A.p(tUne, 0.2, 'softInOut'));
      A.arrow(CX, CY - 290, CX, CY - 170, { progress: A.p(tPress - 0.4, 0.3, 'glide'), color: ac, lw: 10, head: 26, alpha: aa });
    }
  }
}, { shake: shakeAmt });

if (closed) A.flash(tCierra, 0.3, 0.35);

// ---------- CORTE LATERAL (zona secundaria) ----------
const sIn = A.p(0.3, 0.6, 'softLand');
A.with(() => {
  const xL = 240, xR = 840, mx = 540, yTop = 1590, yBot = 1660;
  const d = A.p(tPress - 0.15, 0.25, 'crashIn') * 25 + A.p(tUne - 0.25, 0.3, 'crashIn') * 35;
  // separadores
  A.rect(xL, yTop + 4, 40, yBot - yTop - 8, { fill: '#2a3756' });
  A.rect(xR - 40, yTop + 4, 40, yBot - yTop - 8, { fill: '#2a3756' });
  // lámina inferior (fila)
  const filaOn = t >= tFila, colOn = t >= tCol;
  A.rect(xL, yBot, xR - xL, 10, { fill: filaOn ? ac : '#3a4a6a', glow: filaOn ? 14 : 0 });
  A.rect(mx - 30, yBot - 8, 60, 8, { fill: filaOn ? ac : '#7f8db0' });
  // lámina superior (columna) que se dobla
  ctx.save();
  ctx.strokeStyle = colOn ? c2 : '#7f8db0'; ctx.lineWidth = 8; ctx.lineCap = 'round';
  if (colOn) { ctx.shadowColor = c2; ctx.shadowBlur = 14; }
  ctx.beginPath(); ctx.moveTo(xL, yTop);
  ctx.bezierCurveTo(xL + 180, yTop, mx - 90, yTop + d, mx, yTop + d);
  ctx.bezierCurveTo(mx + 90, yTop + d, xR - 180, yTop, xR, yTop);
  ctx.stroke(); ctx.restore();
  A.rect(mx - 30, yTop + d, 60, 8, { fill: colOn ? c2 : '#c8d2ea' });
  // tecla del corte
  const ky = yTop + d - 14;
  A.rect(mx - 12, ky - 50, 24, 50, { fill: '#c8d2ea' });
  A.rect(mx - 95, ky - 130, 190, 82, { r: 16, fill: '#1e2846', stroke: '#ffffff', lw: 4 });
