  // etiquetas de capa
  if (colOn) A.text('COLUMNA', xL, yTop - 22, { size: 30, color: c2, weight: '800', align: 'left', alpha: A.p(tCol, 0.4, 'softLand') });
  if (filaOn) A.text('FILA', xL, yBot + 52, { size: 30, color: ac, weight: '800', align: 'left', alpha: A.p(tFila, 0.4, 'softLand') });
  // chispa del contacto
  if (t >= tUne) A.circle(mx, yBot - 6, 10 * A.pop(tUne, 0.35), { fill: '#ffffff', glow: 20 });
  if (closed) {
    A.circle(mx, yBot - 6, 16 + 4 * Math.sin((t - tCierra) * 12), { fill: ac, glow: 40, alpha: 0.9 });
    A.rings(mx, yBot - 6, tCierra, { count: 2, speed: 260, gap: 0.2, maxR: 130, color: ac, lw: 4 });
    A.text('CONTACTO', xR, yBot + 52, { size: 30, color: '#ffffff', weight: '800', align: 'right', alpha: A.p(tCierra + 0.15, 0.4, 'softLand') });
  }
}, { alpha: sIn, y: 1550, scale: A.lerp(0.95, 1, sIn) });

const ac = A.accent, P = A.pal || {};
const pale = P.paleBlue || '#9fc3ff', white = '#ffffff';
A.bg('#0b1630', '#050a18', true);

const tChip = A.k('chip', 0.667), tRev = A.k('revisa', 1.0), tCien = A.k('cientos', 3.0);
const tBus = A.k('buscando', 4.667), tCru = A.k('cruce', 5.333), tCer = A.k('cerró', 6.0);

const ROWS = 5, COLS = 6;
const rowY = r => 520 + r * 130;
const colX = c => 430 + c * 108;
const gx0 = 385, gx1 = 1000, gy0 = 470, gy1 = 1090;
const HR = 2, HC = 4;
const hx = colX(HC), hy = rowY(HR);

// ---- posición del barrido ----
const slowP = 0.42;
let s = -1, speed = 0;
if (t >= tRev) {
  if (t < tCien) { s = (t - tRev) / slowP; speed = 1 / slowP; }
  else {
    const s1 = (tCien - tRev) / slowP, dt = t - tCien;
    s = s1 + 2.4 * dt + 12.5 * dt * dt; speed = 2.4 + 25 * dt;
  }
}
const locked = t >= tCru;
const active = locked ? HR : (s >= 0 ? Math.floor(s) % ROWS : -1);
const fast = A.clamp((speed - 3) / 25);

const shake = locked ? 14 * (1 - A.p(tCru, 0.5, 'cruise')) : 0;
const zoom = locked ? 1 + 0.04 * A.p(tCru, 0.35, 'crashIn') - 0.04 * A.p(tCru + 0.35, 0.6, 'softLand') : 1;

A.with(() => {
  const gp = A.p(0, 0.7, 'softLand');
  // placa
  A.rect(gx0 - 20, gy0 - 20, gx1 - gx0 + 40, gy1 - gy0 + 40, { r: 24, fill: 'rgba(20,40,80,0.35)', stroke: 'rgba(159,195,255,0.25)', lw: 2, alpha: gp });

  // columnas
  for (let c = 0; c < COLS; c++) {
    const lit = locked && c === HC;
    A.line([[colX(c), gy0], [colX(c), gy1]], { stroke: lit ? ac : 'rgba(255,255,255,0.35)', lw: lit ? 8 : 4, progress: A.p(0.05 * c, 0.6, 'glide'), alpha: 1 });
  }

  // filas (con barrido)
  for (let r = 0; r < ROWS; r++) {
    const y = rowY(r);
    let glow = 0;
    if (locked) glow = r === HR ? 1 : 0;
    else if (s >= 0) {
      const behind = ((s - r) % ROWS + ROWS) % ROWS;
      const decay = A.lerp(6, 0.9, fast);
      glow = Math.exp(-behind * decay);
      if (fast > 0.3) glow *= 0.6 + 0.4 * A.rand(Math.floor(t * 60) * 7 + r)();
    }
    if (glow > 0.02) A.rect(gx0 - 10, y - 30, gx1 - gx0 + 20, 60, { r: 30, fill: ac, alpha: 0.18 * glow, glow: 30 });
    A.line([[gx0, y], [gx1, y]], { stroke: pale, lw: 5, progress: A.p(0.1 + 0.06 * r, 0.6, 'glide') });
    if (glow > 0.02) A.line([[gx0, y], [gx1, y]], { stroke: ac, lw: 8, alpha: glow });
  }

  // cruces
  for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) {
    const on = r === active && !locked;
    A.circle(colX(c), rowY(r), on ? 9 : 7, { fill: on ? '#ffd2bf' : 'rgba(255,255,255,0.5)', alpha: gp });
  }

  // tecla presionada: contacto cerrado
  if (t >= tBus) {
    const sc = A.pop(tBus, 0.45);
    A.with(() => {
      A.rect(hx - 40, hy - 40, 80, 80, { r: 16, stroke: locked ? ac : white, lw: 4, alpha: 0.9 });
      A.circle(hx, hy, 18, { fill: locked ? ac : 'rgba(255,255,255,0.8)', glow: locked ? 40 : 0 });
    }, { x: hx, y: hy, scale: sc });
    if (!locked) A.arrow(hx, hy - 150, hx, hy - 55, { progress: A.p(tBus, 0.35, 'whip'), color: white, lw: 6 });
  }
  if (locked) A.rings(hx, hy, tCru, { count: 3, speed: 420, gap: 0.18, maxR: 260, color: ac, lw: 5 });
  if (t >= tCer) A.label('¡CERRADO!', hx - 40, hy - 85, { size: 44, bg: ac, color: white, scale: A.pop(tCer, 0.45) });

  // ---- chip ----
  const cs = A.pop(tChip, 0.5);
  const cx = 170, cy = 780;
  // cables
  for (let r = 0; r < ROWS; r++) {
    const py = cy - 100 + r * 50, y = rowY(r);
    const isA = r === active;
    A.line([[cx + 80, py], [300, py], [345, y], [gx0, y]], { stroke: isA ? ac : 'rgba(159,195,255,0.5)', lw: isA ? 6 : 3, progress: A.p(tChip + 0.2 + 0.05 * r, 0.5, 'glide') });
    if (isA && s >= 0 && !locked) {
      const f = s - Math.floor(s);
      const pts = [[cx + 80, py], [300, py], [345, y], [gx0, y]];
      const seg = f * 3, i = Math.min(2, Math.floor(seg)), u = seg - i;
      const px = A.lerp(pts[i][0], pts[i + 1][0], u), pyy = A.lerp(pts[i][1], pts[i + 1][1], u);
      A.circle(px, pyy, 10, { fill: '#ffe0d0', glow: 25 });
    }
  }
  A.with(() => {
    for (let i = 0; i < 6; i++) {
      A.rect(cx - 70 + i * 26, cy - 145, 10, 25, { fill: '#9aa6b8' });
      A.rect(cx - 70 + i * 26, cy + 120, 10, 25, { fill: '#9aa6b8' });
    }
    A.rect(cx - 80, cy - 125, 160, 250, { r: 14, fill: '#1b1f2a', stroke: ac, lw: 4 });
    const pts = [[cx - 80, cy - 125], [cx + 80, cy - 125], [cx + 80, cy + 125], [cx - 80, cy + 125]];
    if (A.lib && A.lib.hatch) A.lib.hatch(ctx, pts, { angle: 45, spacing: 14, width: 1.5, color: 'rgba(255,107,53,0.25)' });
    A.text('CHIP', cx, cy + 15, { size: 42, color: white, weight: 800, align: 'center' });
    const blink = active >= 0 ? (locked ? 1 : (Math.floor(s * 2) % 2 ? 1 : 0.3)) : 0.3;
    A.circle(cx, cy - 70, 12, { fill: ac, alpha: blink, glow: 25 * blink });
  }, { x: cx, y: cy, scale: cs });
}, { x: 540, y: 780, scale: zoom, shake });

if (locked) A.flash(tCru, 0.3, 0.35);

// ---- zona secundaria ----
const sy = 1480;
if (t >= tRev && t < tCien) {
  const n = active + 1;
  const sc = A.pop(tRev + Math.floor(s) * slowP, 0.3);
  A.text('FILA ' + n, 540, sy, { size: 110, color: white, weight: 900, align: 'center', alpha: A.p(tRev, 0.3, 'softLand') });
  A.with(() => A.circle(540, sy + 80, 10, { fill: ac }), { x: 540, y: sy + 80, scale: sc });
} else if (t >= tCien && t < tCru) {
  const p = A.p(tCien, tBus - tCien, 'gentleIn');
  const a = A.p(tCien, 0.3, 'snapSettle');
  A.with(() => {
    A.text(A.counter(1, 500, p, 0) + ' / s', 540, sy, { size: 130, color: ac, weight: 900, align: 'center' });
    A.text('revisiones', 540, sy + 80, { size: 50, color: white, weight: 600, align: 'center', alpha: 0.85 });
  }, { x: 540, y: sy, scale: A.lerp(0.6, 1, a), alpha: a, shake: 3 * fast });
} else if (t >= tCru) {
  const a = A.pop(tCru, 0.45);
  A.with(() => {
    A.text('CRUCE', 540, sy - 10, { size: 110, color: white, weight: 900, align: 'center' });
    A.text('DETECTADO', 540, sy + 90, { size: 80, color: ac, weight: 900, align: 'center' });
  }, { x: 540, y: sy + 40, scale: a });
}

const W=A.W, acc=A.accent;
