  }
  // nodos
  for(let j=0;j<rows;j++)for(let i=0;i<cols;i++){
    if(i===C&&j===R) continue;
    const dim=(t>tX)?0.25:0.6;
    A.circle(x0+i*spx,y0+j*spy,9,{fill:base,alpha:dim*gIn});
  }
  // fila 3
  const pr=A.p(tF+0.05,0.55,'whip');
