  if(pr>0){
    const px=x0-60+((t*900)%(cols*spx+120));
    A.lib.glowDot(ctx,px,cy,14,{color:acc});
    A.with(()=>A.label('F3',95,cy,{size:46,bg:acc,color:'#0b1630'}),{x:95,y:cy,scale:A.pop(tF+0.1)});
  }
  // columna 5
  const pc=A.p(tC+0.05,0.55,'whip');
  const fadeLow=1-A.p(tT-0.1,0.3,'softInOut');
  if(t<tT-0.1){
    A.line([[cx,colTop],[cx,lastY+50]],{stroke:'#ffffff',lw:10,progress:pc,glow:20});
  }else{
