    A.with(()=>A.label('C5',cx,445,{size:46,bg:'#ffffff',color:'#0b1630'}),{x:cx,y:445,scale:A.pop(tC+0.1)});
  }
  // cruce
  if(t>=tX-0.05){
    A.rings(cx,cy,tX,{count:3,speed:260,gap:0.25,maxR:240,color:acc,lw:6});
    const s=A.pop(tX,0.45);
