},{shake});
A.flash(tX,0.18,0.35);
// ecuación en zona secundaria
const ey=1500;
const parts=[['F3',tF+0.1,acc],['×',tC,'#ffffff'],['C5',tC+0.1,'#ffffff'],['=',tT-0.05,'#ffffff'],['G',tT+0.05,acc]];
const xs=[300,420,540,680,800];
parts.forEach((p,i)=>{
